#include "metaLanguageObject.h"

/* PNG */
static const wxString s_translation_64_png = wxT("");

wxIcon ibValueMetaObjectLanguage::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectLanguage::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_translation_64_png, wxSize(16, 16));

	return icon;
}